using NexOS.Forms;

namespace App
{
    public static class Main
    {
        // MiniCLR does NOT run .cctor: every static starts as null/0.
        // All state must be created explicitly inside Init().
        static TaskManagerApp app;

        public static void Init()
        {
            if (app == null) app = new TaskManagerApp();
        }

        public static int Paint(int id, int w, int h)
        {
            Init();
            app.OnPaint(id, w, h);
            return 0;
        }

        public static int Click(int id, int x, int y)
        {
            Init();
            return app.OnClick(id, x, y);
        }

        public static int Key(int id, int ch)
        {
            Init();
            return app.OnKey(id, ch);
        }

        public static string Title(int id)
        {
            Init();
            return app.GetTitle(id);
        }
    }

    public class TaskManagerApp
    {
        // ---- window / document state (assigned in Init, never inline) ----
        string title;
        bool   dirty;
        int    focus;
        int    scroll;
        int    activeTab;

        // TODO(multi-window): one CLR slot per window already isolates
        // statics, but if this app ever shares a slot it MUST keep a
        // fixed-size Doc[] indexed by `id` (linear search, no Dictionary).

        public TaskManagerApp()
        {
            title = "Task Manager";
            dirty = false;
            focus = 0;
            scroll = 0;
            activeTab = 0;
        }

        // ---- layout hit regions (from specs.json) ---------------------
        const int X_tabs = 8, Y_tabs = 8, W_tabs = 544, H_tabs = 28;
        const int X_cpu = 8, Y_cpu = 44, W_cpu = 260, H_cpu = 100;
        const int X_mem = 276, Y_mem = 44, W_mem = 276, H_mem = 100;
        const int X_procs = 8, Y_procs = 152, W_procs = 544, H_procs = 220;
        const int X_kill = 452, Y_kill = 380, W_kill = 100, H_kill = 28;

        static bool InRect(int x, int y, int rx, int ry, int rw, int rh)
        {
            return x >= rx && x < rx + rw && y >= ry && y < ry + rh;
        }

        public void OnPaint(int id, int w, int h)
        {
            // Only draw here.  Do NOT create objects that must survive
            // the frame: the bump heap is rewound after every Paint.
            // Client size is w x h; the constants above are prototype
            // coordinates and should be re-derived from w/h when the
            // kernel starts honouring per-app window sizes.
            W.Label(X_tabs, Y_tabs, "页签");  // TODO: draw tabs
            W.Label(X_cpu, Y_cpu, "CPU");  // TODO: draw chart
            W.Label(X_mem, Y_mem, "内存");  // TODO: draw chart
            W.Label(X_procs, Y_procs, "进程表");  // TODO: draw grid
            W.Button(X_kill, Y_kill, W_kill, H_kill, "结束任务");
            // TODO: scrollbars, selection highlight, dirty marker,
            //       and any state-dependent greying-out of controls.
        }

        public int OnClick(int id, int x, int y)
        {
            // Return non-zero when the click is consumed by the app.
            // Coordinates are client-relative (mforms subtracts ox/oy).
            if (InRect(x, y, X_tabs, Y_tabs, W_tabs, H_tabs))
            {
                // TODO: tabs -> 页签
                activeTab = 0;  // TODO: derive from x/y
                dirty = true;
                return 1;
            }
            if (InRect(x, y, X_procs, Y_procs, W_procs, H_procs))
            {
                // TODO: grid -> 进程表
                activeTab = 0;  // TODO: derive from x/y
                dirty = true;
                return 1;
            }
            if (InRect(x, y, X_kill, Y_kill, W_kill, H_kill))
            {
                // TODO: button -> 结束任务
                dirty = true;
                return 1;
            }
            return 0;
        }

        public int OnKey(int id, int ch)
        {
            // Return non-zero when consumed (Tab MUST be consumed so the
            // window manager does not move focus away).
            // TODO: obtain the authoritative key code table from
            // mforms_key -> gui_legacy.cpp before implementing these:
            //   Delete       -> 结束选中进程
            //   Up           -> 上一行
            //   Down         -> 下一行
            //   F5           -> 刷新
            if (ch == 9) return 1;   // Tab placeholder
            return 0;
        }

        public string GetTitle(int id)
        {
            // TODO: append the document name and a (saved) hint with
            // U.Cat -- never use string '+'.  clr_heap_mark/reset wraps
            // this call in mforms_title(), so the string is temporary.
            return title;
        }
    }
}
